INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beb7eb8b-3e98-5595-b828-87332388a1ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$An IS-IS router has the overload bit set. Transit traffic arrives at the router. What is the expected result?$$::text, $$[{"id": "A", "text": "The router avoids transit paths and is used only for directly connected destinations.", "is_correct": true}, {"id": "B", "text": "The pseudowire remains down until LDP session to the remote PE is established.", "is_correct": false}, {"id": "C", "text": "The next-hop remains unchanged unless 'neighbor next-hop-self' is configured.", "is_correct": false}, {"id": "D", "text": "LOCAL_PREF is not present on eBGP-learned routes by default.", "is_correct": false}]$$::jsonb, $$Given An IS-IS router has the overload bit set. and Transit traffic arrives at the router., the result is: The router avoids transit paths and is used only for directly connected destinations.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$1.0 IGP$$::text, 10.0, '20b9fe2aad586fe0', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb5f7ef6-03cd-5d08-9e86-38e4b8be4405', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A Layer 3 VPN site advertises a route with route target 65000:100. The receiving PE has a VRF importing 65000:100. What is the expected result?$$::text, $$[{"id": "A", "text": "The router avoids transit paths and is used only for directly connected destinations.", "is_correct": false}, {"id": "B", "text": "The route is installed into the matching VRF routing table.", "is_correct": true}, {"id": "C", "text": "LOCAL_PREF is not present on eBGP-learned routes by default.", "is_correct": false}, {"id": "D", "text": "The next-hop remains unchanged unless 'neighbor next-hop-self' is configured.", "is_correct": false}]$$::jsonb, $$Given A Layer 3 VPN site advertises a route with route target 65000:100. and The receiving PE has a VRF importing 65000:100., the result is: The route is installed into the matching VRF routing table.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$7.0 Layer 3 VPN$$::text, 10.0, '0162286b58535526', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57631bc2-67e0-507e-9428-f55633b968e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A route reflector client advertises a route to its route reflector. The route reflector reflects the route to other clients. What is the expected result?$$::text, $$[{"id": "A", "text": "The route is installed into the matching VRF routing table.", "is_correct": false}, {"id": "B", "text": "The local PE installs the MAC in its bridge domain forwarding table.", "is_correct": false}, {"id": "C", "text": "The intra-area path is preferred regardless of cost.", "is_correct": false}, {"id": "D", "text": "The next-hop remains unchanged unless 'neighbor next-hop-self' is configured.", "is_correct": true}]$$::jsonb, $$Given A route reflector client advertises a route to its route reflector. and The route reflector reflects the route to other clients., the result is: The next-hop remains unchanged unless 'neighbor next-hop-self' is configured.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$2.0 BGP$$::text, 15.0, 'bb10db485c32437f', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd2240b8-8321-52e4-a7c0-7a586e86325c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A router's Routing Engine fails. GRES and NSR are configured. What is the expected result?$$::text, $$[{"id": "A", "text": "The pseudowire remains down until LDP session to the remote PE is established.", "is_correct": false}, {"id": "B", "text": "The local PE installs the MAC in its bridge domain forwarding table.", "is_correct": false}, {"id": "C", "text": "The intra-area path is preferred regardless of cost.", "is_correct": false}, {"id": "D", "text": "Forwarding continues using the backup RE with no protocol disruption.", "is_correct": true}]$$::jsonb, $$Given A router's Routing Engine fails. and GRES and NSR are configured., the result is: Forwarding continues using the backup RE with no protocol disruption.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$9.0 High Availability$$::text, 5.0, 'ca66d65190ee5024', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

