INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e649464e-c0a3-5dd8-8658-4512094d9611', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A Layer 2 VPN pseudowire is signaled using LDP. The remote PE is unreachable. What is the expected result?$$::text, $$[{"id": "A", "text": "The route is installed into the matching VRF routing table.", "is_correct": false}, {"id": "B", "text": "LOCAL_PREF is not present on eBGP-learned routes by default.", "is_correct": false}, {"id": "C", "text": "The local PE installs the MAC in its bridge domain forwarding table.", "is_correct": false}, {"id": "D", "text": "The pseudowire remains down until LDP session to the remote PE is established.", "is_correct": true}]$$::jsonb, $$Given A Layer 2 VPN pseudowire is signaled using LDP. and The remote PE is unreachable., the result is: The pseudowire remains down until LDP session to the remote PE is established.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$8.0 Layer 2 VPN$$::text, 10.0, 'beea4c7c043f03eb', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d316ba07-0153-5112-86f7-1839cb53f109', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A PIM-SM receiver joins a multicast group. No active source exists yet. What is the expected result?$$::text, $$[{"id": "A", "text": "The intra-area path is preferred regardless of cost.", "is_correct": false}, {"id": "B", "text": "The receiver's DR sends a (*,G) join toward the RP.", "is_correct": true}, {"id": "C", "text": "The route is installed into the matching VRF routing table.", "is_correct": false}, {"id": "D", "text": "Forwarding continues using the backup RE with no protocol disruption.", "is_correct": false}]$$::jsonb, $$Given A PIM-SM receiver joins a multicast group. and No active source exists yet., the result is: The receiver's DR sends a (*,G) join toward the RP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$3.0 IP Multicast$$::text, 10.0, '865abd651d56ecdd', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('742c244d-dff8-5eab-8c16-31a9912549db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$A BGP router receives a route with no LOCAL_PREF attribute. The route is received from an eBGP peer. What is the expected result?$$::text, $$[{"id": "A", "text": "LOCAL_PREF is not present on eBGP-learned routes by default.", "is_correct": true}, {"id": "B", "text": "The router avoids transit paths and is used only for directly connected destinations.", "is_correct": false}, {"id": "C", "text": "The intra-area path is preferred regardless of cost.", "is_correct": false}, {"id": "D", "text": "The route is installed into the matching VRF routing table.", "is_correct": false}]$$::jsonb, $$Given A BGP router receives a route with no LOCAL_PREF attribute. and The route is received from an eBGP peer., the result is: LOCAL_PREF is not present on eBGP-learned routes by default.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$2.0 BGP$$::text, 15.0, '746158df084d4aff', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('978b8984-7514-5c64-8371-5d418a0c0209', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$An EVPN PE receives a Type 2 route for a MAC address. The MAC is reachable via a remote PE. What is the expected result?$$::text, $$[{"id": "A", "text": "The route is installed into the matching VRF routing table.", "is_correct": false}, {"id": "B", "text": "The local PE installs the MAC in its bridge domain forwarding table.", "is_correct": true}, {"id": "C", "text": "Forwarding continues using the backup RE with no protocol disruption.", "is_correct": false}, {"id": "D", "text": "The pseudowire remains down until LDP session to the remote PE is established.", "is_correct": false}]$$::jsonb, $$Given An EVPN PE receives a Type 2 route for a MAC address. and The MAC is reachable via a remote PE., the result is: The local PE installs the MAC in its bridge domain forwarding table.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$6.0 EVPN$$::text, 10.0, 'f9ff77447fe02273', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87592631-c414-58a0-9548-75c3f9b25366', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', $$An OSPF router receives two paths to the same destination. One path is intra-area and the other is inter-area. What is the expected result?$$::text, $$[{"id": "A", "text": "Forwarding continues using the backup RE with no protocol disruption.", "is_correct": false}, {"id": "B", "text": "The receiver's DR sends a (*,G) join toward the RP.", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF is not present on eBGP-learned routes by default.", "is_correct": false}, {"id": "D", "text": "The intra-area path is preferred regardless of cost.", "is_correct": true}]$$::jsonb, $$Given An OSPF router receives two paths to the same destination. and One path is intra-area and the other is inter-area., the result is: The intra-area path is preferred regardless of cost.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$1.0 IGP$$::text, 10.0, '731897a607ec88e3', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('373faf33-0cee-53fb-9300-cf74842b9f2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$How many full adjacencies are on ge-0/0/0.0?

user@PE1> show ospf neighbor
Address          Interface              State     ID               Pri  Dead
10.1.1.2         ge-0/0/0.0             Full      2.2.2.2          128    33
10.1.1.3         ge-0/0/0.0             2Way      3.3.3.3            0    38$$::text, $$[{"id": "A", "text": "0", "is_correct": false}, {"id": "B", "text": "1", "is_correct": true}, {"id": "C", "text": "2", "is_correct": false}, {"id": "D", "text": "3", "is_correct": false}]$$::jsonb, $$On a broadcast network, full adjacencies are formed only with DR/BDR. Only one neighbor is in Full state.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$1.0 IGP$$::text, 10.0, 'e0d25413abaa09e7', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dd5e6fb-dea7-5b91-ba2d-c51e4bcd083c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$Which peer is an iBGP peer?

user@PE1> show bgp summary
Groups: 1 Peers: 2 Down peers: 0
Peer                     AS      InPkt     OutPkt    OutQ   Flaps Last Up/Dwn State|#Active/Received/Accepted/Damped...
10.0.0.2              65002      1200       1200       0       0    1d 2:10:10 Establ
  inet.0: 50/50/50/0
10.0.0.3              65001      1100       1100       0       0    2d 1:05:00 Establ
  inet.0: 100/100/100/0$$::text, $$[{"id": "A", "text": "10.0.0.2 in AS 65002", "is_correct": false}, {"id": "B", "text": "10.0.0.3 in AS 65001", "is_correct": true}, {"id": "C", "text": "Both are iBGP peers", "is_correct": false}, {"id": "D", "text": "Neither is an iBGP peer", "is_correct": false}]$$::jsonb, $$The local AS is 65001. 10.0.0.3 has the same AS, so it is iBGP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$2.0 BGP$$::text, 15.0, 'b521524deef7a58d', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c750656-8ddb-5231-8cc5-081e3658f4d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$Which protocol installed the route in the VPN routing table?

user@PE1> show route table vpn-a.inet.0

vpn-a.inet.0: 3 destinations, 3 routes (3 active, 0 holddown, 0 hidden)
+ = Active Route, - = Last Active, * = Both

10.10.0.0/24     *[BGP/170] 00:05:12, localpref 100
                      AS path: I, validation-state: unverified
                    > to 10.0.0.4 via ge-0/0/1.0$$::text, $$[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "Static", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]$$::jsonb, $$The route is marked [BGP/170], indicating it was learned via BGP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$7.0 Layer 3 VPN$$::text, 10.0, '15323976acb72776', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

