INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab0d739-2354-54c0-b3cf-7df5d8229176', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which Junos CoS components can classify or mark traffic? (Choose two.)$$::text, $$[{"id": "A", "text": "Policer", "is_correct": false}, {"id": "B", "text": "Buffer", "is_correct": false}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Rewrite rule", "is_correct": true}, {"id": "E", "text": "Queue", "is_correct": false}, {"id": "F", "text": "Classifier", "is_correct": true}]$$::jsonb, $$Classifiers map traffic to forwarding classes; rewrite rules change DSCP/CoS bits. Schedulers/policers manage bandwidth/drop.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$5.0 CoS$$::text, 10.0, '4dadb19a89f1dae2', true) ON CONFLICT (id) DO NOTHING;
