INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ede060-7c51-54a9-b4e4-0e38dc868ce8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which EVPN route types are used for MAC/IP advertisement? (Choose two.)$$::text, $$[{"id": "A", "text": "Type 4", "is_correct": false}, {"id": "B", "text": "Type 3", "is_correct": false}, {"id": "C", "text": "Type 2", "is_correct": true}, {"id": "D", "text": "Type 1", "is_correct": false}, {"id": "E", "text": "Type 5", "is_correct": true}]$$::jsonb, $$Type 2 carries MAC/IP, Type 5 carries IP prefixes. Type 1 is Ethernet A-D, Type 3 inclusive multicast, Type 4 Ethernet segment.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$6.0 EVPN$$::text, 10.0, '014214072b249411', true) ON CONFLICT (id) DO NOTHING;
