INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39842bcc-8f04-51c7-bb26-6b80f2703b97', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which BGP attributes are well-known mandatory? (Choose two.)$$::text, $$[{"id": "A", "text": "Community", "is_correct": false}, {"id": "B", "text": "NEXT_HOP", "is_correct": true}, {"id": "C", "text": "MED", "is_correct": false}, {"id": "D", "text": "LOCAL_PREF", "is_correct": false}, {"id": "E", "text": "AS_PATH", "is_correct": true}]$$::jsonb, $$AS_PATH and NEXT_HOP are well-known mandatory. LOCAL_PREF is well-known discretionary. MED and Community are optional.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$2.0 BGP$$::text, 15.0, 'bd1dfe26e5069888', true) ON CONFLICT (id) DO NOTHING;
