INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e1e9726-bd63-5db3-a5a9-24080c21195e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which statements about Junos bridge domains are true? (Choose two.)$$::text, $$[{"id": "A", "text": "Storm control is a Layer 3 feature", "is_correct": false}, {"id": "B", "text": "IRB is only for MPLS", "is_correct": false}, {"id": "C", "text": "A bridge domain is a Layer 2 forwarding entity", "is_correct": true}, {"id": "D", "text": "IRB provides Layer 3 routing for a bridge domain", "is_correct": true}, {"id": "E", "text": "Bridge domains replace routing tables", "is_correct": false}]$$::jsonb, $$Bridge domains provide Layer 2 forwarding; IRB interfaces route between VLANs/bridge domains.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$4.0 Ethernet Switching$$::text, 10.0, 'fd57bb14ae3cf007', true) ON CONFLICT (id) DO NOTHING;
