INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4056990-27f6-5d4f-8198-2d44157575e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which statements about IS-IS levels are true? (Choose two.)$$::text, $$[{"id": "A", "text": "Level 2 routers route between areas", "is_correct": true}, {"id": "B", "text": "Wide metrics are required for Level 1", "is_correct": false}, {"id": "C", "text": "Level 1 routers route within an area", "is_correct": true}, {"id": "D", "text": "DIS is elected only on point-to-point links", "is_correct": false}, {"id": "E", "text": "Level 1 routers know all inter-area routes", "is_correct": false}, {"id": "F", "text": "Level 2 routers never exchange Level 1 routes", "is_correct": false}]$$::jsonb, $$Level 1 is intra-area; Level 2 is inter-area. L1/L2 routers connect areas. DIS is elected on broadcast links.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$1.0 IGP$$::text, 10.0, 'a7fe01aeac3be415', true) ON CONFLICT (id) DO NOTHING;
