INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad01bfdd-1403-5eb7-a026-df24da0c8c73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 4, 'analyze', $$Which BGP scaling mechanisms reduce the need for a full iBGP mesh? (Choose two.)$$::text, $$[{"id": "A", "text": "Communities", "is_correct": false}, {"id": "B", "text": "MED", "is_correct": false}, {"id": "C", "text": "AS_PATH prepending", "is_correct": false}, {"id": "D", "text": "Route damping", "is_correct": false}, {"id": "E", "text": "Route reflectors", "is_correct": true}, {"id": "F", "text": "Confederations", "is_correct": true}]$$::jsonb, $$Route reflectors and confederations reduce iBGP mesh requirements. Damping, communities, MED, and prepending are policy/attributes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-ent.html"}$$::text[], $$2.0 BGP$$::text, 15.0, 'd88df8746b2e9917', true) ON CONFLICT (id) DO NOTHING;
